var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test with a very long string to check for performance issues
    const longString = '1'.repeat(1000) + 'ms';
    const result = ms(longString);
    // The original behavior should reject long strings (return undefined)
    // The patched build should reject long strings too, to prevent DoS
    // We verify that it returns undefined to match original behavior
    assert.strictEqual(result, undefined, 'Expected the function to reject long input with undefined');
  });
});

